#include "cloudmoon_protocol.h"
#include <stdio.h>
#include <string.h>
static int json_string(char *out,size_t cap,const char *s){size_t n=0;if(!s)s="";if(cap<3)return -1;out[n++]='"';while(*s){unsigned char c=(unsigned char)*s++;if(c=='"'||c=='\\'){if(n+2>=cap)return -1;out[n++]='\\';out[n++]=(char)c;}else if(c<0x20){if(n+6>=cap)return -1;if(snprintf(out+n,cap-n,"\\u%04x",c)!=6)return -1;n+=6;}else{if(n+1>=cap)return -1;out[n++]=(char)c;}}if(n+2>cap)return -1;out[n++]='"';out[n]=0;return (int)n;}
cm_eio_type_t cm_eio_packet_type(const char*p){if(!p||!p[0])return CM_EIO_INVALID;switch(p[0]){case '0':return CM_EIO_NOOP;case '1':return CM_EIO_CLOSE;case '2':return CM_EIO_PING;case '3':return CM_EIO_PONG;case '4':return CM_EIO_MESSAGE;case '5':return CM_EIO_SEND_UPGRADE;case '6':return CM_EIO_NOOP;default:return CM_EIO_INVALID;}}
int cm_eio_make_pong(char*out,size_t cap){if(!out||cap<2)return -1;out[0]='3';out[1]=0;return 1;}
int cm_socketio_make_connect(char*out,size_t cap){if(!out||cap<3)return -1;memcpy(out,"40",3);return 2;}
int cm_socketio_make_event(char*out,size_t cap,const char*event,const char*json){char q[256];int n;if(!out||!event||!json||json_string(q,sizeof(q),event)<0)return -1;n=snprintf(out,cap,"42[%s,%s]",q,json);return n<0||(size_t)n>=cap?-1:n;}
int cm_socketio_make_register(char*out,size_t cap,const char*room_id,const char*client_id){char r[512],c[256],p[900];int n;if(!room_id||!client_id||json_string(r,sizeof(r),room_id)<0||json_string(c,sizeof(c),client_id)<0)return -1;n=snprintf(p,sizeof(p),"{\"roomid\":%s,\"clientid\":%s}",r,c);if(n<0||(size_t)n>=sizeof(p))return -1;return cm_socketio_make_event(out,cap,"register",p);}
int cm_socketio_make_client_register(char*out,size_t cap,int w,int h,const char*game,const char*uid,const char*iid){char g[512],u[512],in[2048],slot[1100],qs[1200],p[3600];int n,s;if(w<=0||h<=0||!game||!uid||!iid)return -1;if(json_string(g,sizeof(g),game)<0||json_string(u,sizeof(u),uid)<0||json_string(in,sizeof(in),iid)<0)return -1;s=snprintf(slot,sizeof(slot),"%s@%s",uid,game);if(s<0||(size_t)s>=sizeof(slot)||json_string(qs,sizeof(qs),slot)<0)return -1;n=snprintf(p,sizeof(p),"{\"screenRes\":\"%dx%d\",\"game\":%s,\"userId\":%s,\"slotId\":%s,\"instanceId\":%s}",w,h,g,u,qs,in);if(n<0||(size_t)n>=sizeof(p))return -1;return cm_socketio_make_event(out,cap,"client_register",p);}
